-- db-r15-5. `ctrlz declare-lost user_totp` wrote one notice and one audit row PER CALL, and the Go
-- caller cut the list into calls of 500 seeds, so a tenant with 1100 lost seeds got three warnings
-- and three audit events that said 500, 500 and 100: a log that reads as three smaller operations,
-- and as a complete smaller one when the run stopped after the first. One declaration is one record.
--
-- The limit of 1000 existed because the match was array_position() per row, quadratic in the list.
-- The list is a join now (unnest, on the primary key), linear in its length, so a call takes up to
-- 20000 seeds and the caller cuts only a list longer than that. The whole declaration is one
-- transaction (the caller's WithTenant), so a run cannot stop half way; the trail row of a call says
-- exactly what that call cleared, and a tenant with more than 20000 lost seeds (the one case left
-- with more than one record) gets one accurate record per 20000.
--
-- The rule is unchanged: a row is cleared only while it holds exactly the ciphertext the caller
-- proved lost and names the key number; the notice and the audit row are written by the same call.
-- Same signature, so CREATE OR REPLACE keeps the grant and functions.yaml needs no line.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION ctrlz_fn.keytool_totp_declare_lost(p_key_number integer, p_user_ids uuid[], p_cts bytea[])
RETURNS integer
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  v_tenant uuid := ctrlz.current_tenant_id();
  v_n      integer;
BEGIN
  IF v_tenant IS NULL OR p_key_number IS NULL OR p_key_number NOT BETWEEN 1 AND 65535
     OR p_user_ids IS NULL OR p_cts IS NULL
     OR pg_catalog.cardinality(p_user_ids) <> pg_catalog.cardinality(p_cts)
     OR pg_catalog.cardinality(p_user_ids) = 0 THEN
    RETURN 0;
  END IF;
  IF pg_catalog.cardinality(p_user_ids) > 20000 THEN
    RAISE EXCEPTION 'keytool_totp_declare_lost: at most 20000 seeds per call' USING ERRCODE = '22023';
  END IF;
  -- Header: 'C' 'Z', format version 1, then the key number as two bytes (keyring).
  UPDATE ctrlz.users u
     SET totp_secret_ct = NULL, totp_enabled_at = NULL, totp_last_step = NULL
    FROM unnest(p_user_ids, p_cts) AS l(id, ct)
   WHERE u.tenant_id = v_tenant AND u.id = l.id AND u.totp_enabled_at IS NOT NULL
     AND u.totp_secret_ct IS NOT NULL
     -- The ciphertext listed for this user is still the one stored.
     AND u.totp_secret_ct = l.ct
     AND pg_catalog.octet_length(u.totp_secret_ct) >= 5
     AND pg_catalog.get_byte(u.totp_secret_ct, 0) = 67
     AND pg_catalog.get_byte(u.totp_secret_ct, 1) = 90
     AND pg_catalog.get_byte(u.totp_secret_ct, 2) = 1
     AND pg_catalog.get_byte(u.totp_secret_ct, 3) * 256 + pg_catalog.get_byte(u.totp_secret_ct, 4) = p_key_number;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    INSERT INTO ctrlz.notifications (tenant_id, kind, severity, params)
    VALUES (v_tenant, 'totp_lost', 'warning', '{}');
    INSERT INTO ctrlz.tenant_audit_log (tenant_id, user_id, action, target, params)
    VALUES (v_tenant, NULL, 'totp.declared_lost', NULL,
            pg_catalog.jsonb_build_object('key_number', p_key_number, 'users', v_n));
  END IF;
  RETURN v_n;
END
$$;
